import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;

public class Main {
  private static final String KEY = "0123456789abcdef"; // 16byteデモ用

  public static void main(String[] args) throws Exception {
    String enc = encrypt("hello");
    String dec = decrypt(enc);
    System.out.println(enc + " -> " + dec);
  }

  static String encrypt(String plain) throws Exception {
    Cipher c = Cipher.getInstance("AES");
    c.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(KEY.getBytes(), "AES"));
    byte[] out = c.doFinal(plain.getBytes());
    return Base64.getEncoder().encodeToString(out);
  }

  static String decrypt(String enc) throws Exception {
    Cipher c = Cipher.getInstance("AES");
    c.init(Cipher.DECRYPT_MODE, new SecretKeySpec(KEY.getBytes(), "AES"));
    byte[] in = Base64.getDecoder().decode(enc);
    return new String(c.doFinal(in));
  }
}

