public class DiffUtil {
  public static Set<String> diffKeys(Map<String, ?> a, Map<String, ?> b) {
    Set<String> keys = new HashSet<>();
    keys.addAll(a.keySet());
    keys.addAll(b.keySet());
    Set<String> diff = new HashSet<>();
    for (String k : keys) {
