import java.util.*;

public class ExpiringCache<K,V> {
  private static class Entry<V> { V v; long expireAt; }
  private final long ttlMs;
  private final Map<K,Entry<V>> map = new HashMap<>();
  public ExpiringCache(long ttlMs) { this.ttlMs = ttlMs; }
  public synchronized void put(K k, V v) {
    Entry<V> e = new Entry<>(); e.v = v; e.expireAt = System.currentTimeMillis() + ttlMs; map.put(k, e);
  }
  public synchronized V get(K k) {
    Entry<V> e = map.get(k);
    if (e == null || e.expireAt < System.currentTimeMillis()) { map.remove(k); return null; }
    return e.v;
  }
}

